## Large Dataset Export (Streaming)
```typescript
@Get('posts/csv')
async exportPostsCsv(@Res() res: Response) {
  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', 'attachment; filename="posts.csv"');

  // Write header
  res.write('id,title,createdAt\n');

  // Stream in batches
  let offset = 0;
  const batchSize = 1000;

  while (true) {
    const batch = await db.select().from(posts)
      .limit(batchSize)
      .offset(offset);

    if (batch.length === 0) break;

    for (const post of batch) {
      res.write(`${post.id},"${post.title}",${post.createdAt}\n`);
    }

    offset += batchSize;
  }

  res.end();
}
```

